/*
 * A127243  Triangle whose k-th column is generated by (1+A010060(1+k)x)*x^k.
 * https://oeis.org/A127243
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   Let r = floor((sqrt(8*n+1)-1)/2) and c = n - r*(r+1)/2. Then
 *            a(n) = 1 if c==r (main diagonal) or (c==r-1 and popcount(r) is
 *            odd); otherwise a(n)=0
 * Range:     u8 n <= 90, u16 n <= 90, u32 n <= 90, u64 n <= 90, u128 n <= 90,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

static idx_t
row_of(idx_t n) {
    idx_t low = 0;
    idx_t high = n;          /* Upper bound is n, binary search is O(log n). */
    while (low < high) {
        idx_t mid = low + (high - low + 1) / 2;
        __int128 t = (__int128)mid * (mid + 1) / 2;
        if (t <= n) low = mid;
        else high = mid - 1;
    }
    return low;
}

seq_t
a(idx_t n) {
    idx_t r = row_of(n);
    /* Compute base = r*(r+1)/2 using 128-bit to avoid overflow. */
    __int128 base128 = (__int128)r * (r + 1) / 2;
    idx_t base = (idx_t)base128;
    idx_t c = n - base;

    if (c == r) return (seq_t)1;
    if (c + 1 == r) {
        /* Parity of popcount(r). */
        return (seq_t)((__builtin_popcountll(r) & 1) ? 1 : 0);
    }
    return (seq_t)0;
}
